// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        // Admissible domain: any value; SetMinSum can be called before initialization.
        // Reference always succeeds on first SetMinSum (guard only blocks AFTER Initialized).
        c.SetMinSum(firstVal);
        c.Initialized();

        uint256 minBefore = c.MinSum();

        // After initialization, the reference MUST revert on SetMinSum.
        bool ok = true;
        try c.SetMinSum(secondVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok == false (reverts), so MinSum stays firstVal -> firstVal == minBefore.
        // Mutant: ok == true, MinSum becomes secondVal -> differs whenever secondVal != firstVal.
        assertTrue(ok == false && c.MinSum() == minBefore);
    }
}
